import { arrowGenerator } from "../../helpers";
import { StyleFn } from "..";

export const Popover: StyleFn = (theme, mode) => {
  const { color, font, elevation, size } = theme;
  const backgroundColor = color.surface.elevation[3][mode];
  const { root: arrowRoot, arrow } = arrowGenerator(8, backgroundColor);

  return {
    root: {
      position: "absolute",
      fontSize: font.size.small,
      lineHeight: font.lineheight.small,
      color: color.text.neutral.default[mode],
      borderRadius: size.radius[3],
      backgroundColor,
      boxShadow: elevation.level3,
      zIndex: elevation.zindex.popover,
      ...arrowRoot,
    },
    arrow,
    arrow_center: {
      marginLeft: `calc(50% - 4px)`,
    },
    content: {
      padding: size.spacing[8],
    },
    _high: {
      boxShadow: elevation.level6,
      backgroundColor: color.surface.elevation[6][mode],
      "& $arrow:before": {
        backgroundColor: color.surface.elevation[6][mode],
      }
    },
    _low: {
      boxShadow: elevation.level1,
      backgroundColor: color.surface.elevation[1][mode],
      "& $arrow:before": {
        backgroundColor: color.surface.elevation[1][mode],
      }
    },
  };
};
